function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof DURAND_INFO&&(n.innerHTML=DURAND_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderTrophies(){const n=document.getElementById("trophies-grid");n&&"undefined"!=typeof THREE_TROPHIES&&(n.innerHTML=THREE_TROPHIES.map(n=>`\n        <div class="trophy-card">\n            <span class="trophy-icon">${n.icon}</span>\n            <h3>${n.name}</h3>\n            <span class="origin-tag">Instituted: ${n.origin}</span>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderClubs(){const n=document.getElementById("clubs-grid");n&&"undefined"!=typeof SUCCESSFUL_CLUBS&&(n.innerHTML=SUCCESSFUL_CLUBS.map(n=>`\n        <div class="club-card">\n            <div class="card-header">\n                <h3>⚽ ${n.club}</h3>\n                <span class="titles-badge">${n.titles} Titles</span>\n            </div>\n            <p><strong>Runners-Up:</strong> ${n.runnersUp} times | <strong>First Crown:</strong> ${n.firstTitle}</p>\n            <p class="era-text">${n.era}</p>\n        </div>\n    `).join(""))}function renderVenues(){const n=document.getElementById("venues-grid");n&&"undefined"!=typeof HISTORIC_VENUES&&(n.innerHTML=HISTORIC_VENUES.map(n=>`\n        <div class="venue-card">\n            <span class="era-badge">${n.era}</span>\n            <h3>🏟️ ${n.name}</h3>\n            <p>${n.significance}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TOURNAMENT_MILESTONES&&(n.innerHTML=TOURNAMENT_MILESTONES.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTrophies(),renderClubs(),renderVenues(),renderTimeline(),renderReferences(),initThemeToggle()});